def increasing_bst_brute(root):
    values = []
    def collect(node):
        if node:
            collect(node.left); values.append(node.val); collect(node.right)
    collect(root)
    dummy = TreeNode(0)
    cur = dummy
    for v in values:
        cur.right = TreeNode(v)              # create a BRAND NEW node
        cur = cur.right
    return dummy.right

