public class Main {
    static TreeNode cur;
    static TreeNode increasingBST(TreeNode root) {
        TreeNode dummy = new TreeNode(0);
        cur = dummy;
        inorder(root);
        return dummy.right;
    }
    static void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        node.left = null;                          // clear left pointer
        cur.right = node;                            // attach as tail's right child
        cur = node;                                    // update tail
        inorder(node.right);
    }
}

